// Daily Safe Batching, Smart Prioritization & Cleaner
// Priority 1: Builders WITHOUT a website FIRST
// Priority 2: Lowest Rating & Lowest Reviews FIRST (highest pain/urgency)
const MAX_BATCH_PER_DAY = 20; 

const items = $input.all();
if (!items || items.length === 0) return [];

// 1. Clean and normalize all incoming leads
const parsedLeads = items.map(item => {
  const row = item.json;

  const businessName = (row['Business'] || row['Business Name'] || 'Valued Builder').trim();
  const category = (row['Category'] || 'Construction contractor').trim();
  const address = (row['Address'] || '').trim();
  const pincode = (row['Pincode'] || '').toString().trim();
  const rating = parseFloat(row['Rating']) || 0;
  const reviews = parseInt(row['Reviews']) || 0;
  const gmapLink = (row['Google Maps link'] || '').trim();
  const website = (row['Website'] || '').trim();
  const email = (row['Email'] || '').trim().toLowerCase();

  // Clean Phone number
  let rawPhone = (row['Phone'] || '').toString().replace(/[^0-9+]/g, '');
  if (rawPhone && !rawPhone.startsWith('+')) {
    if (rawPhone.length === 10) rawPhone = '+91' + rawPhone;
    else if (rawPhone.length === 12 && rawPhone.startsWith('91')) rawPhone = '+' + rawPhone;
  }

  // Determine Website presence (exclude generic social/directories)
  const isSocialOrDir = /(facebook\.com|instagram\.com|indiamart\.com|justdial\.com|linkedin\.com)/i.test(website);
  const hasDedicatedWebsite = Boolean(website && website.length > 7 && !isSocialOrDir);

  // Extract Location hint
  let city = 'Madurai';
  if (address.toLowerCase().includes('coimbatore')) city = 'Coimbatore';
  else if (address.toLowerCase().includes('chennai')) city = 'Chennai';
  else if (address.toLowerCase().includes('trichy')) city = 'Trichy';

  return {
    businessName,
    category,
    phone: rawPhone,
    email,
    website,
    address,
    pincode,
    city,
    rating,
    reviews,
    gmapLink,
    hasDedicatedWebsite,
    originalRow: row
  };
});

// 2. Sort by User Directive:
// Rule A: Without Website comes FIRST (hasDedicatedWebsite === false)
// Rule B: Low Rating comes FIRST (lowest rating/reviews have highest pain)
parsedLeads.sort((a, b) => {
  // Priority 1: Without website first
  if (!a.hasDedicatedWebsite && b.hasDedicatedWebsite) return -1;
  if (a.hasDedicatedWebsite && !b.hasDedicatedWebsite) return 1;

  // Priority 2: Lowest Rating first (ascending, e.g. 3.5 before 4.2 before 4.9)
  if (a.rating !== b.rating) {
    return a.rating - b.rating;
  }

  // Priority 3: Lowest Review count first
  return a.reviews - b.reviews;
});

// 3. Slice the prioritized top 20 leads for today
const dailyBatch = parsedLeads.slice(0, MAX_BATCH_PER_DAY);

return dailyBatch.map(lead => ({ json: lead }));

// Random Jitter (15 to 30 seconds) between sends
// Prevents Render proxy connection drops while maintaining safe human pacing
const min = 15;
const max = 30;
const delaySeconds = Math.floor(Math.random() * (max - min + 1)) + min;

return [{
  json: {
    delaySeconds
  }
}];
